#include <iostream>
#include <iomanip>
#include <string>
#include <stdexcept>

// Base class representing a commission employee
class CommissionEmployee {
public:
    CommissionEmployee(const std::string& first, const std::string& last, 
                       const std::string& ssn, double sales = 0.0, double rate = 0.0)
        : firstName(first), lastName(last), socialSecurityNumber(ssn) {
        setGrossSales(sales);
        setCommissionRate(rate);
    }

    void setGrossSales(double sales) {
        if (sales < 0.0) {
            throw std::invalid_argument("Gross sales must be >= 0.0");
        }
        grossSales = sales;
    }
    double getGrossSales() const { return grossSales; }

    void setCommissionRate(double rate) {
        if (rate <= 0.0 || rate >= 1.0) {
            throw std::invalid_argument("Commission rate must be > 0.0 and < 1.0");
        }
        commissionRate = rate;
    }
    double getCommissionRate() const { return commissionRate; }

    const std::string& getFirstName() const { return firstName; }
    const std::string& getLastName() const { return lastName; }
    const std::string& getSocialSecurityNumber() const { return socialSecurityNumber; }

    double earnings() const { return commissionRate * grossSales; }

    void print() const {
        std::cout << "commission employee: " << firstName << ' ' << lastName
                  << "\nsocial security number: " << socialSecurityNumber
                  << "\ngross sales: " << grossSales
                  << "\ncommission rate: " << commissionRate;
    }

private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
    double grossSales{0.0};
    double commissionRate{0.0};
};

// Derived class demonstrating public inheritance syntax and extension
class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(const std::string& first, const std::string& last,
                               const std::string& ssn, double sales = 0.0,
                               double rate = 0.0, double salary = 0.0)
        : CommissionEmployee(first, last, ssn, sales, rate) {
        setBaseSalary(salary);
    }

    void setBaseSalary(double salary) {
        if (salary < 0.0) {
            throw std::invalid_argument("Salary must be >= 0.0");
        }
        baseSalary = salary;
    }
    double getBaseSalary() const { return baseSalary; }

    // Overridden earnings calculates base salary + commission earnings
    double earnings() const {
        return baseSalary + CommissionEmployee::earnings();
    }

    void print() const {
        std::cout << "base-salaried ";
        CommissionEmployee::print();
        std::cout << "\nbase salary: " << baseSalary;
    }

private:
    double baseSalary{0.0};
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    BasePlusCommissionEmployee emp("Bob", "Lewis", "333-33-3333", 5000.0, 0.04, 300.0);

    std::cout << "Employee information obtained by get functions:\n"
              << "First name is " << emp.getFirstName()
              << "\nLast name is " << emp.getLastName()
              << "\nSocial security number is " << emp.getSocialSecurityNumber()
              << "\nGross sales is " << emp.getGrossSales()
              << "\nCommission rate is " << emp.getCommissionRate()
              << "\nBase salary is " << emp.getBaseSalary() << "\n\n";

    emp.setBaseSalary(1000.0);

    std::cout << "Updated employee information output by print function:\n";
    emp.print();
    std::cout << "\n\nEmployee's earnings: $" << emp.earnings() << std::endl;

    return 0;
}
